// The type-level gate of the semver surface (round 2, plugin-api-types-owned-by-internal-contracts).
// The plugin API re-exports about 60 types from the internal-stable contracts package, and the runtime allowlist test sees only runtime names.
// This script builds the declarations of @tessera/contracts, @tessera/plugin-api and @tessera/react/ui, joins the files reachable from each entry
// and compares the text with the committed snapshots in poc/api/*.d.ts. A change of a type that a plugin can see fails `npm run check` until
// someone runs `npm run api:update` and commits the diff on purpose. It over-approximates (a private field shows too), which is the safe side.
// An API extractor (api-extractor) stays deferred (ADR-014); this is one script.
// Usage: node scripts/api-snapshot.mjs [check|update]
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(join(root, 'package.json'));
const tscBin = join(dirname(require.resolve('typescript/package.json')), 'bin', 'tsc');
const mode = process.argv[2] ?? 'check';
const apiDir = join(root, 'api');

const surfaces = [
  { name: 'contracts', pkg: 'contracts', entry: 'index.d.ts' },
  { name: 'plugin-api', pkg: 'plugin-api', entry: 'index.d.ts' },
  { name: 'react-ui', pkg: 'react', entry: 'ui.d.ts' },
];

// Build the declarations (incremental, a few hundred ms when nothing changed).
try {
  execFileSync(process.execPath, [tscBin, '-b', ...[...new Set(surfaces.map((s) => `packages/${s.pkg}/tsconfig.build.json`))]], { cwd: root, stdio: 'pipe', encoding: 'utf8' });
} catch (error) {
  console.error(String(error.stdout ?? '') + String(error.stderr ?? ''));
  console.error('api-snapshot: the build failed');
  process.exit(1);
}

/** The declaration files reachable from the entry through relative imports and re-exports, in a stable order. */
function reachable(distDir, entry) {
  const seen = new Map();
  const visit = (file) => {
    if (seen.has(file)) return;
    const text = readFileSync(join(distDir, file), 'utf8');
    seen.set(file, text);
    for (const match of text.matchAll(/from\s+['"](\.[^'"]+)['"]|import\(\s*['"](\.[^'"]+)['"]\s*\)/g)) {
      const spec = match[1] ?? match[2];
      const target = join(dirname(file), spec).replace(/\.(m?js|ts)$/, '.d.ts');
      if (existsSync(join(distDir, target))) visit(target);
    }
  };
  visit(entry);
  return [...seen].toSorted(([a], [b]) => a.localeCompare(b));
}

function snapshotOf(surface) {
  const distDir = join(root, 'packages', surface.pkg, 'dist');
  const files = reachable(distDir, surface.entry);
  const parts = [`// Declaration snapshot of ${surface.name}. Generated by scripts/api-snapshot.mjs; update with "npm run api:update".`];
  for (const [file, text] of files) {
    parts.push(`\n// ===== ${file} =====`);
    parts.push(text.replace(/\/\/# sourceMappingURL=.*$/gm, '').trimEnd());
  }
  return `${parts.join('\n')}\n`;
}

let failed = 0;
for (const surface of surfaces) {
  const text = snapshotOf(surface);
  const target = join(apiDir, `${surface.name}.d.ts`);
  if (mode === 'update') {
    mkdirSync(apiDir, { recursive: true });
    writeFileSync(target, text);
    console.log(`api-snapshot: wrote ${relative(root, target)} (${text.split('\n').length} lines)`);
    continue;
  }
  if (!existsSync(target)) {
    console.error(`api-snapshot: ${relative(root, target)} is missing; run "npm run api:update"`);
    failed++;
    continue;
  }
  const committed = readFileSync(target, 'utf8');
  if (committed !== text) {
    failed++;
    const a = committed.split('\n');
    const b = text.split('\n');
    let i = 0;
    while (i < a.length && i < b.length && a[i] === b[i]) i++;
    console.error(`api-snapshot: the public declarations of ${surface.name} changed (first difference at line ${i + 1}):`);
    console.error(`  committed: ${a[i] ?? '(end)'}`);
    console.error(`  now:       ${b[i] ?? '(end)'}`);
    console.error('  A change of this surface is a semver decision. If it is on purpose, run "npm run api:update" and commit api/*.d.ts.');
  }
}
if (failed > 0) process.exit(1);
if (mode === 'check') console.log(`api-snapshot: ok (${surfaces.map((s) => s.name).join(', ')})`);
